num=r'\d+(?:\.\d+)?'
def parseopt(s):
 m=re.fullmatch(r'[A-E]\)\s*([+-]?\d+(?:\.\d+)?(?:/\d+)?)\s*([a-zA-Z /.%]*)[.]?',s.strip())
 if not m:return None
 try:return F(m[1]),m[2].strip().lower()
 except Exception:return None
